//autogenerated:yes
//nolint:revive,govet,errcheck
package ardupilotmega_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/ardupilotmega"
	"github.com/stretchr/testify/require"
)

func TestEnum_SECURE_COMMAND_OP(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.SECURE_COMMAND_OP
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.SECURE_COMMAND_GET_SESSION_KEY.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.SECURE_COMMAND_OP
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.SECURE_COMMAND_GET_SESSION_KEY, dec)
	})
}
